// Keyed by map name, as battle states carry it.
export const MAPS: Record<string, string> = { 黑松隘口: mapPinepass, 平原会战: mapPlains, 山间隘口: mapPass, 林中遭遇: mapWoods };
export const CRESTS: Record<string, string> = { raven: crestRaven, frost: crestFrost };
export const STAGE = stagePass;
export const SPARK = fxSpark;
export const VULNERARY = icoVulnerary;

const SPRITES: Record<ClassId, [string, string]> = {
  swordsman: [unitSwordAlly, unitSwordEnemy],
  fighter: [unitAxeAlly, unitAxeEnemy],
  knight: [unitArmorAlly, unitArmorEnemy],
  cavalier: [unitCavAlly, unitCavEnemy],
  pegasus: [unitPegAlly, unitPegEnemy],
  archer: [unitArcherAlly, unitArcherEnemy],
  mage: [unitMageAlly, unitMageEnemy],
  cleric: [unitClericAlly, unitClericEnemy],
};

const PORTRAITS: Record<string, string> = {
  erin: porErin, karl: porKarl, victor: porVictor, lina: porLina, owen: porOwen,
  sera: porSera, noah: porNoah, gustav: porGustav, brock: porBrock,
};

const WEAPON_ICONS: Record<WeaponType, string> = {
  sword: icoSword, lance: icoLance, axe: icoAxe, bow: icoBow, tome: icoTome, staff: icoStaff,
};

type Looks = Pick<UnitState, 'classId' | 'side'> & { character?: string; id?: string };

// Map sprites face right for allies and left for enemies.
export function spriteFor(unit: Looks): string {
  return SPRITES[unit.classId][unit.side === 'player' ? 0 : 1];
}

// Named units have portraits; generic enemies borrow the bandit face only when they are fighters.
export function portraitFor(unit: Looks): string | null {
  const own = PORTRAITS[unit.character ?? unit.id ?? ''];
  if (own) return own;
  return unit.classId === 'fighter' ? porGruntAxe : null;
}

// Side-view sprites (44px, shown at 4x) exist for a few units; the rest use the map sprite at 8x.
export function fighterFor(unit: UnitState): string | null {
  if (unit.character === 'erin') return fightErin;
  if (unit.side === 'enemy' && unit.classId === 'fighter') return fightAxe;
  return null;
}

export function weaponIcon(type: WeaponType): string {
  return WEAPON_ICONS[type];
}
